class TaskBinding {static Object book(int id,String[]authors,String publisher,int year){return new Book(id,(id==1?"Первая":id==2?"Вторая":id==3?"Третья":"T"+id),authors,publisher,year,100,10,"Твёрдый");}static Object[] array(Object...values){return java.util.Arrays.copyOf(values,values.length,Book[].class);}static Book[] books(Object[]a){return (Book[])a;}static Object[] author(Object[]a,String s){return Book.author(books(a),s);}static Object[] publisher(Object[]a,String s){return Book.publisher(books(a),s);}static Object[] after(Object[]a,int y){return Book.after(books(a),y);}static String state(Object a){Book b=(Book)a;return b.id()+"|"+b.title()+"|"+java.util.Arrays.toString(b.authors())+"|"+b.publisher()+"|"+b.year()+"|"+b.pages()+"|"+b.price()+"|"+b.binding();}static java.util.List<?> value(Object x){Book item=(Book)x;return java.util.List.of(item.id(),item.title(),java.util.List.of(item.authors()),item.publisher(),item.year(),item.pages(),item.price(),item.binding());}}
